const { chromium } = require('C:/Users/human-01/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({headless:true,channel:"msedge"});
  const page = await browser.newPage({viewport:{width:1440,height:1050},deviceScaleFactor:1});
  const errors=[];
  page.on('pageerror',error=>errors.push(error.message));
  await page.goto('http://127.0.0.1:3001/__design');
  await page.getByText('나를 위한 작은 변화.',{exact:false}).waitFor();
  await page.screenshot({path:'C:/Users/human-01/Desktop/stevil/data-collection/wegovy/rag/cache/design-desktop.png',fullPage:true});
  await page.getByRole('button',{name:'위고비 궁금하세요? AI 도우미에게 질문하기'}).click();
  await page.getByRole('dialog').waitFor();
  await page.screenshot({path:'C:/Users/human-01/Desktop/stevil/data-collection/wegovy/rag/cache/design-chat.png'});
  await page.getByLabel('위고비 질문',{exact:true}).fill('화면 예시를 보여 주세요');
  await page.getByRole('button',{name:'질문 보내기'}).click();
  await page.getByText('디자인 미리보기 · 실제 검색이나 API 요청은 전송하지 않았습니다.').waitFor();
  await page.keyboard.press('Escape');
  await page.setViewportSize({width:390,height:844});
  await page.screenshot({path:'C:/Users/human-01/Desktop/stevil/data-collection/wegovy/rag/cache/design-mobile.png',fullPage:true});
  const overflow=await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth);
  console.log(JSON.stringify({errors,mobileOverflow:overflow}));
  await browser.close();
  if(errors.length||overflow)process.exitCode=1;
})();
